const STORE='pfd_design_projects_v1';
let supabaseClient=null;
let authSession=null;
let authUser=null;
function initSupabase(){
  const cfg=window.PFD_SUPABASE_CONFIG||{};
  if(!cfg.url||!cfg.anonKey||cfg.url.includes('YOUR_PROJECT')||cfg.anonKey.includes('YOUR_ANON_KEY')) return null;
  if(!window.supabase?.createClient) return null;
  try{return window.supabase.createClient(cfg.url,cfg.anonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}})}catch(e){console.error(e);return null}
}
function supabaseReady(){return !!supabaseClient}
function applyTheme(t){document.body.classList.toggle('dark',t==='dark');localStorage.setItem('diagram_designer_theme_v1',t);document.querySelectorAll('[data-theme-choice]').forEach(b=>b.classList.toggle('active',b.dataset.themeChoice===t))}
function setTheme(t){applyTheme(t)}
let guestProjects=[];
let guestMode=false;
function startGuest(){guestMode=true;guestProjects=[];closeAuth();document.getElementById('landing').style.display='none';document.getElementById('dashboard').style.display='block';document.getElementById('dashUser').innerHTML='<span class="guest-badge">Modo invitado · No se guardará nada</span>';renderProjects();toast('Entraste sin cuenta. Tus proyectos son temporales.')}
function projectStore(){try{return JSON.parse(localStorage.getItem(STORE)||'{}')}catch(e){return {}}}
function currentEmail(){return authUser?.email||''}
function toast(t){let x=document.getElementById('toast');x.textContent=t;x.style.display='block';setTimeout(()=>x.style.display='none',2600)}
function openAuth(type){document.getElementById('authLayer').classList.add('show');renderAuth(type)}
function closeAuth(){document.getElementById('authLayer').classList.remove('show')}
let authMode='login';
function renderAuth(type){authMode=type;let c=document.getElementById('authContent');let heading=type==='signup'?'Crear cuenta':'Iniciar sesión';c.innerHTML=`<h2>${heading}</h2><input class="auth-email" id="authEmail" type="email" placeholder="Dirección de correo electrónico" autocomplete="email"><button class="auth-continue" onclick="emailContinue()">Continuar</button><div class="auth-extra">${supabaseReady()?'Acceso seguro con correo electrónico':'Configura Supabase para activar las cuentas reales'}</div><a class="auth-back" onclick="renderAuth('${type==='signup'?'login':'signup'}')">${type==='signup'?'¿Ya tienes cuenta? Iniciar sesión':'¿No tienes cuenta? Crear cuenta'}</a>`}
function emailContinue(){let email=(document.getElementById('authEmail').value||'').trim().toLowerCase();if(!email||!/^\S+@\S+\.\S+$/.test(email)){toast('Ingresa un correo electrónico válido');return}if(!supabaseReady()){renderConfigRequired();return}renderPasswordStage(email,authMode)}
function renderConfigRequired(){document.getElementById('authContent').innerHTML=`<h2>Configuración pendiente</h2><p class="auth-sub" style="text-align:center">La autenticación real requiere conectar el proyecto de Supabase.</p><div class="auth-extra">Añade la URL del proyecto y la clave anon/public en <b>supabase-config.js</b> para activar el registro y el inicio de sesión.</div><a class="auth-back" onclick="renderAuth('${authMode}')">Volver</a>`}
function renderPasswordStage(email,mode){let c=document.getElementById('authContent');if(mode==='signup'){c.innerHTML=`<h2>Crear tu cuenta</h2><p class="auth-sub" style="text-align:center">Regístrate con ${escapeHtml(email)}</p><form class="auth-stage-form" onsubmit="signup(event,'${escapeHtml(email)}')"><div class="form-field"><label>Nombre</label><input id="name" autocomplete="name" placeholder="Tu nombre" required maxlength="80"></div><div class="form-field"><label>Contraseña</label><input id="password" type="password" autocomplete="new-password" minlength="8" placeholder="Mínimo 8 caracteres" required></div><button class="auth-continue" id="authSubmit">Crear cuenta</button></form><a class="auth-back" onclick="renderAuth('signup')">← Volver</a>`}else{c.innerHTML=`<h2>Bienvenido de nuevo</h2><p class="auth-sub" style="text-align:center">${escapeHtml(email)}</p><form class="auth-stage-form" onsubmit="login(event,'${escapeHtml(email)}')"><div class="form-field"><label>Contraseña</label><input id="password" type="password" autocomplete="current-password" placeholder="Tu contraseña" required></div><button class="auth-continue" id="authSubmit">Iniciar sesión</button></form><a class="auth-back" onclick="renderAuth('login')">← Volver</a><a class="auth-back" onclick="resetPassword('${escapeHtml(email)}')">¿Olvidaste tu contraseña?</a>`}}
async function signup(e,emailFixed){e.preventDefault();if(!supabaseReady()){renderConfigRequired();return}let name=document.getElementById('name').value.trim(),email=emailFixed,pw=document.getElementById('password').value,btn=document.getElementById('authSubmit');btn.disabled=true;btn.textContent='Creando cuenta…';try{const {data,error}=await supabaseClient.auth.signUp({email,password:pw,options:{data:{full_name:name}}});if(error)throw error;if(data.session){authSession=data.session;authUser=data.user;closeAuth();showDashboard();toast('¡Cuenta creada!')}else{document.getElementById('authContent').innerHTML=`<h2>Revisa tu correo</h2><p class="auth-sub" style="text-align:center">Enviamos un enlace de confirmación a <b>${escapeHtml(email)}</b>. Confirma tu correo para poder iniciar sesión.</p><a class="auth-back" onclick="renderAuth('login')">Volver a iniciar sesión</a>`}}catch(err){btn.disabled=false;btn.textContent='Crear cuenta';toast(authError(err.message))}}
async function login(e,emailFixed){e.preventDefault();if(!supabaseReady()){renderConfigRequired();return}let email=emailFixed,pw=document.getElementById('password').value,btn=document.getElementById('authSubmit');btn.disabled=true;btn.textContent='Iniciando…';try{const {data,error}=await supabaseClient.auth.signInWithPassword({email,password:pw});if(error)throw error;authSession=data.session;authUser=data.user;closeAuth();showDashboard();toast('Sesión iniciada')}catch(err){btn.disabled=false;btn.textContent='Iniciar sesión';toast(authError(err.message))}}
async function resetPassword(email){if(!supabaseReady())return;try{const cfg=window.PFD_SUPABASE_CONFIG||{};const {error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:cfg.redirectUrl||window.location.href});if(error)throw error;toast('Te enviamos un enlace para restablecer tu contraseña')}catch(err){toast(authError(err.message))}}
function authError(m){m=String(m||'');if(/invalid login credentials/i.test(m))return 'Correo o contraseña incorrectos.';if(/already registered|user already exists/i.test(m))return 'Ese correo ya está registrado. Inicia sesión.';if(/password.*(weak|short)|at least/i.test(m))return 'La contraseña debe tener al menos 8 caracteres.';if(/email not confirmed/i.test(m))return 'Confirma tu correo antes de iniciar sesión.';if(/rate limit/i.test(m))return 'Demasiados intentos. Espera un momento y vuelve a intentarlo.';return m||'No se pudo completar la operación.'}
async function logout(){if(guestMode){guestProjects=[];guestMode=false;}if(supabaseClient){try{await supabaseClient.auth.signOut()}catch(e){console.error(e)}}authSession=null;authUser=null;document.getElementById('dashboard').style.display='none';document.getElementById('workspace').style.display='none';document.getElementById('landing').style.display='block'}
function showDashboard(){guestMode=false;if(!authUser){logout();return}document.querySelector('.dashheading h1').textContent='Mis proyectos';document.getElementById('dashDescription').textContent='Tu espacio de trabajo personal.';document.getElementById('landing').style.display='none';document.getElementById('dashboard').style.display='block';let display=authUser.user_metadata?.full_name||authUser.email;document.getElementById('dashUser').textContent=display+' · '+authUser.email;renderProjects()}
async function renderProjects(){
 let box=document.getElementById('projects');box.innerHTML='';
 if(guestMode){document.querySelector('.dashheading h1').textContent='Espacio temporal';document.getElementById('dashDescription').textContent='Puedes crear proyectos de prueba, pero al salir o cerrar la página se perderán.';if(!guestProjects.length){box.innerHTML=`<div class="project-card empty-card"><div style="font-size:30px;color:#654eea">＋</div><b>Tu espacio está vacío</b><p style="margin:8px 0">Crea un proyecto temporal para comenzar.</p><button class="btn primary" style="margin-top:12px" onclick="newProject()">Crear proyecto</button></div>`;return}guestProjects.forEach(p=>renderProjectCard(p,true));return}
 document.querySelector('.dashheading h1').textContent='Mis proyectos';document.getElementById('dashDescription').textContent='Tu espacio de trabajo personal.';
 if(!supabaseReady()||!authUser){box.innerHTML='<p>No se pudo conectar con la base de datos. Verifica tu conexión e inicia sesión nuevamente.</p>';return}
 box.innerHTML='<div class="project-card empty-card"><p>⏳ Cargando tus proyectos…</p></div>';
 try{
  // Importa los proyectos locales de esta cuenta una sola vez, si la tabla remota está vacía.
  const {data:remote,error}=await supabaseClient.from('pfd_projects').select('id,name,created_at').eq('user_id',authUser.id).order('created_at',{ascending:true});
  if(error)throw error;
  const local=projectStore(),old=(local[currentEmail()]||{projects:[]}).projects||[];
  if((remote||[]).length===0&&old.length){
    const rows=old.map(p=>({user_id:authUser.id,name:p.name,created_at:parseProjectDate(p.date)}));
    const {error:insertError}=await supabaseClient.from('pfd_projects').insert(rows);if(insertError)throw insertError;
    const {data:again,error:againError}=await supabaseClient.from('pfd_projects').select('id,name,created_at').eq('user_id',authUser.id).order('created_at',{ascending:true});if(againError)throw againError;renderRemoteProjects(again||[]);toast('Tus proyectos locales se sincronizaron con tu cuenta');return;
  }
  renderRemoteProjects(remote||[]);
 }catch(err){console.error('Load projects:',err);box.innerHTML=`<div class="project-card empty-card"><b>No pudimos cargar tus proyectos</b><p style="margin:8px 0">${escapeHtml(err.message||'Error de conexión')}</p><button class="btn" onclick="renderProjects()">Reintentar</button></div>`}
}
function parseProjectDate(date){if(!date)return new Date().toISOString();let parts=String(date).split('/');if(parts.length===3){let d=new Date(Number(parts[2]),Number(parts[1])-1,Number(parts[0]));return d.toISOString()}return date}
function renderRemoteProjects(projects){let box=document.getElementById('projects');box.innerHTML='';if(!projects.length){box.innerHTML=`<div class="project-card empty-card"><div style="font-size:30px;color:#654eea">＋</div><b>Aún no tienes proyectos</b><p style="margin:8px 0">Crea tu primer espacio de diseño.</p><button class="btn primary" style="margin-top:12px" onclick="newProject()">Crear proyecto</button></div>`;return}projects.forEach(p=>renderProjectCard({id:p.id,name:p.name,date:new Date(p.created_at).toLocaleDateString('es-CO')},false))}
function renderProjectCard(p,isGuest){let box=document.getElementById('projects');let card=document.createElement('div');card.className='project-card';card.innerHTML=`<div class="project-preview"><div class="preview-node"></div><span>→</span><div class="preview-node"></div><span>→</span><div class="preview-node"></div></div><h3>${escapeHtml(p.name)}</h3><p>${isGuest?'Proyecto temporal · No guardado':'Creado: '+escapeHtml(p.date||'')}</p><div class="card-actions"><button class="btn primary" onclick="openProject('${p.id}')">Abrir</button><button class="btn" onclick="deleteProject('${p.id}')">Eliminar</button></div>`;box.appendChild(card)}
async function newProject(){let name=prompt('Nombre de tu proyecto:','Nuevo proyecto de proceso');if(!name||!name.trim())return;if(guestMode){guestProjects.push({id:'g'+Date.now(),name:name.trim(),date:new Date().toLocaleDateString('es-CO')});renderProjects();toast('Proyecto temporal creado');return}if(!supabaseReady()||!authUser){toast('Debes iniciar sesión para guardar proyectos');return}try{const {data,error}=await supabaseClient.from('pfd_projects').insert({user_id:authUser.id,name:name.trim()}).select('id,name,created_at').single();if(error)throw error;renderProjectCard({id:data.id,name:data.name,date:new Date(data.created_at).toLocaleDateString('es-CO')},false);toast('Proyecto creado y guardado en tu cuenta')}catch(err){console.error(err);toast('No se pudo crear el proyecto: '+(err.message||''));renderProjects()}}
async function openProject(id){let p;if(guestMode)p=guestProjects.find(x=>x.id===id);else{const card=document.querySelector(`button[onclick="openProject('${id}')"]`)?.closest('.project-card');p={id,name:card?.querySelector('h3')?.textContent||'Proyecto'};}if(!p)return;activeProject={id:p.id,name:p.name||'Proyecto',info:p.info||{},diagram:p.diagram||{},pfdDiagram:p.pfdDiagram||null};if(!guestMode&&supabaseClient){try{const {data,error}=await supabaseClient.from('pfd_projects').select('id,name,project_info,diagram,pfd_diagram').eq('id',id).eq('user_id',authUser.id).single();if(error)throw error;activeProject.name=data.name;activeProject.info=data.project_info||{};activeProject.diagram=data.diagram||{};activeProject.pfdDiagram=data.pfd_diagram||null;}catch(err){console.warn('No se pudo cargar la columna PFD remota (ejecuta la migración Etapa 23); se intentará con los datos disponibles:',err.message);try{const {data,error}=await supabaseClient.from('pfd_projects').select('id,name,project_info,diagram').eq('id',id).eq('user_id',authUser.id).single();if(!error&&data){activeProject.name=data.name;activeProject.info=data.project_info||{};activeProject.diagram=data.diagram||{};}}catch(e){console.warn(e)} } }const blockLocal=localStorage.getItem('pfd-blocks-v1-'+id);if(!activeProject.diagram?.nodes?.length&&blockLocal){try{activeProject.diagram=JSON.parse(blockLocal)}catch(e){}}document.getElementById('dashboard').style.display='none';document.getElementById('workspace').style.display='block';document.getElementById('wsProjectName').textContent=activeProject.name;document.getElementById('wsUser').textContent=authUser?.email||'Modo temporal';workspacePage('home')}
let projectLogoData='';function openProjectInfo(){if(!activeProject)return;const info=activeProject.info||{};document.getElementById('piName').value=activeProject.name||'';document.getElementById('piOrganization').value=info.organization||'';document.getElementById('piDate').value=info.date||new Date().toISOString().slice(0,10);document.getElementById('piReviewer').value=info.reviewer||'';document.getElementById('piMembers').value=Array.isArray(info.members)?info.members.join('\n'):(info.members||'');projectLogoData=info.logo||'';renderProjectLogoPreview();document.getElementById('projectInfoLayer').classList.add('show')}
function closeProjectInfo(){document.getElementById('projectInfoLayer').classList.remove('show')}
function renderProjectLogoPreview(){const box=document.getElementById('piLogoPreview');if(!box)return;box.innerHTML=projectLogoData?`<img src="${projectLogoData}" alt="Logo del proyecto">`:'Vista previa<br>del logo'}
function handleProjectLogo(e){const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Selecciona un archivo de imagen');e.target.value='';return}if(file.size>8*1024*1024){toast('La imagen debe pesar menos de 8 MB');e.target.value='';return}const img=new Image(),reader=new FileReader();reader.onload=()=>{img.onload=()=>{const max=600,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);projectLogoData=canvas.toDataURL('image/jpeg',0.82);renderProjectLogoPreview()};img.src=reader.result};reader.readAsDataURL(file)}
function removeProjectLogo(){projectLogoData='';document.getElementById('piLogoFile').value='';renderProjectLogoPreview()}
async function saveProjectInfo(){if(!activeProject)return;const btn=document.getElementById('piSaveButton');const newName=document.getElementById('piName').value.trim();if(!newName){toast('El nombre del proyecto es obligatorio');return}const info={organization:document.getElementById('piOrganization').value.trim(),date:document.getElementById('piDate').value,reviewer:document.getElementById('piReviewer').value.trim(),members:document.getElementById('piMembers').value.split('\n').map(x=>x.trim()).filter(Boolean),logo:projectLogoData};btn.disabled=true;btn.textContent='Guardando…';try{if(guestMode){const p=guestProjects.find(x=>x.id===activeProject.id);if(p){p.name=newName;p.info=info}activeProject.name=newName;activeProject.info=info}else{const {error}=await supabaseClient.from('pfd_projects').update({name:newName,project_info:info}).eq('id',activeProject.id).eq('user_id',authUser.id);if(error)throw error;activeProject.name=newName;activeProject.info=info}document.getElementById('wsProjectName').textContent=newName;closeProjectInfo();toast('Información del proyecto guardada')}catch(err){console.error('Save project info:',err);toast('No se pudo guardar. Verifica que ejecutaste el SQL de actualización: '+(err.message||''))}finally{btn.disabled=false;btn.textContent='Guardar información'}}
let activeProject=null;
function backToProjects(){document.getElementById('workspace').style.display='none';document.getElementById('dashboard').style.display='block';renderProjects()}

