async function saveDiagram(autosave=false){if(!activeProject)return;if(diagramSaveInFlight){diagramAutosaveTimer=setTimeout(()=>saveDiagram(true),1200);return}const d=structuredClone(getDiagram()),snapshot=JSON.stringify(d);try{localStorage.setItem('pfd-blocks-v1-'+activeProject.id,snapshot)}catch(e){}let btn=document.querySelector('.blocks-head-actions button[onclick="saveDiagram()"]');if(btn&&!autosave){btn.disabled=true;btn.textContent='Guardando…'}diagramSaveInFlight=true;try{if(guestMode){let p=guestProjects.find(p=>p.id===activeProject.id);if(p)p.diagram=d;activeProject.diagram=d;diagramDirty=false;const st=document.getElementById('diagramStatus');if(st)st.textContent='Guardado local temporal (invitado)';if(!autosave)toast('Diagrama guardado temporalmente')}else{if(!supabaseClient||!authUser)throw new Error('Sesión no disponible');const {error}=await supabaseClient.from('pfd_projects').update({diagram:d}).eq('id',activeProject.id).eq('user_id',authUser.id);if(error)throw error;activeProject.diagram=d;diagramDirty=JSON.stringify(getDiagram())!==snapshot;const st=document.getElementById('diagramStatus');if(st)st.textContent=diagramDirty?'Cambios nuevos · guardando…':'Guardado en la nube ✓';if(!autosave)toast('Diagrama guardado en tu proyecto')} }catch(err){console.error(err);const st=document.getElementById('diagramStatus');if(st)st.textContent='Guardado local · pendiente de sincronizar';if(!autosave)toast('Se conservó una copia local, pero no se pudo sincronizar con Supabase: '+(err.message||''))}finally{diagramSaveInFlight=false;if(btn&&!autosave){btn.disabled=false;btn.textContent='💾 Guardar'}if(diagramDirty&&!guestMode&&authUser&&supabaseClient){clearTimeout(diagramAutosaveTimer);diagramAutosaveTimer=setTimeout(()=>saveDiagram(true),1200)}}}
document.addEventListener('keydown',e=>{const editor=document.querySelector('.blocks-concept');if(!editor)return;const active=document.activeElement,tag=active?.tagName?.toLowerCase();if(['input','textarea','select'].includes(tag)||active?.isContentEditable)return;const inEditor=editor.contains(active)||active===document.body;if(!inEditor)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?diagramRedo():diagramUndo();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();diagramRedo();return}if(e.key==='Delete'||e.key==='Backspace'){if(selectedNodeId){e.preventDefault();deleteDiagramNode(selectedNodeId)}return}if(e.key==='F11'){e.preventDefault();toggleDiagramFullscreen();return}if(e.key==='Tab'&&document.getElementById('diagramViewport')?.contains(active)){e.preventDefault();const ns=getDiagram().nodes;if(!ns.length)return;let i=ns.findIndex(n=>n.id===selectedNodeId);i=(i+(e.shiftKey?-1:1)+ns.length)%ns.length;selectedNodeId=ns[i].id;renderDiagram();document.getElementById('diagramViewport')?.focus({preventScroll:true});}});
let currentBlocksTab='basic';
function setBlocksTab(tab,btn){currentBlocksTab=tab;document.querySelectorAll('.palette-tab').forEach(b=>b.classList.toggle('active',b===btn));const labels={basic:'ELEMENTOS BÁSICOS',arrows:'LÍNEAS Y CONECTORES',extras:'ELEMENTOS ADICIONALES'};document.getElementById('paletteSectionName').textContent=labels[tab];drawBlockPalette()}
function drawBlockPalette(){const grid=document.getElementById('paletteGrid');if(!grid)return;const list=blockPaletteData[currentBlocksTab];document.getElementById('paletteCount').textContent=list.length;const q=(document.getElementById('blockSearch')?.value||'').toLowerCase();grid.innerHTML=list.filter(x=>x[2].toLowerCase().includes(q)).map((x,i)=>`<button class="palette-item" onclick="selectBlockTool('${x[0]}','${x[2]}')" title="${x[2]}"><span class="shape-icon ${x[0]}">${x[0]==='arrow'||x[0]==='line'||x[0]==='link'?x[1]:''}</span><span>${x[2]}</span></button>`).join('')||'<div style="grid-column:1/-1;color:#8795a1;font-size:11px;padding:10px">No se encontraron elementos.</div>'}
function filterBlockPalette(){drawBlockPalette()}

