function workspacePage(page){const content=document.getElementById('wsContent');const workspace=document.getElementById('workspace');workspace.classList.toggle('editor-clean',['blocks','pfd','pfd3d'].includes(page));document.querySelectorAll('#wsNav button').forEach(b=>b.classList.toggle('active',b.dataset.wsPage===page));if(page==='home'){content.innerHTML=`<div class="ws-welcome"><div><h1>¿Qué quieres crear hoy?</h1><p>Empieza a diseñar dentro de tu proyecto o continúa con tus herramientas.</p></div><div class="ws-project-pill">Proyecto: <strong>${escapeHtml(activeProject?.name||'')}</strong></div></div><h2 class="ws-section-title">Tus herramientas de diseño</h2><div class="ws-tool-grid"><div class="ws-tool-card" onclick="workspacePage('blocks')"><div class="ws-tool-icon">▦</div><h3>Diagrama de bloques</h3><p>Representa las etapas principales de un proceso, conecta operaciones y organiza el flujo de trabajo.</p><button class="btn primary">Continuar editando →</button></div><div class="ws-tool-card" onclick="workspacePage('pfd')"><div class="ws-tool-icon">⚙</div><h3>Diagrama PFD</h3><p>Diseña un diagrama de flujo de procesos con equipos, corrientes y operaciones de ingeniería.</p><button class="btn primary">Abrir herramienta PFD →</button></div><div class="ws-tool-card" onclick="workspacePage('pfd3d')"><div class="ws-tool-icon">◈</div><h3>PFD 3D</h3><p>Visualiza y desarrolla procesos industriales en un entorno tridimensional. Esta herramienta se proyecta para una etapa futura.</p><button class="btn primary">Explorar PFD 3D →</button></div></div><h2 class="ws-section-title" style="margin-top:30px">Accesos rápidos</h2><div class="ws-secondary-grid"><div class="ws-secondary-card" onclick="workspacePage('documents')"><span style="font-size:22px">▤</span><div><strong>Mis documentos</strong><small>PDF generados</small></div></div><div class="ws-secondary-card" onclick="workspacePage('templates')"><span style="font-size:22px">▧</span><div><strong>Plantillas</strong><small>Comienza con un diseño</small></div></div><div class="ws-secondary-card" onclick="workspacePage('favorites')"><span style="font-size:22px">☆</span><div><strong>Favoritos</strong><small>Acceso rápido</small></div></div></div>`;return;}if(page==='blocks'){renderBlocksConcept();return;}if(page==='pfd'){renderPfdLibrary();return;}if(page==='pfd3d'){pfdOpen3DFromDiagram();return;}const pages={blocks:{icon:'▦',title:'Diagramas de bloques',desc:'Crea y edita diagramas de bloques para representar procesos de ingeniería.',action:'El editor de diagramas de bloques se conectará en la siguiente etapa.'},pfd:{icon:'⚙',title:'Diagramas PFD',desc:'Diseña diagramas de flujo de procesos con equipos y corrientes de proceso.',action:'Diseña diagramas de flujo de procesos con equipos y corrientes de proceso.'},pfd3d:{icon:'◈',title:'PFD 3D',desc:'Explora una planta industrial en 3D como un videojuego.',action:'Entra a la planta industrial y explórala en primera experiencia 3D.'},documents:{icon:'▤',title:'Mis documentos',desc:'Aquí se centralizarán los PDF que generes dentro de PFD Design.',action:'Todavía no hay documentos PDF guardados en este proyecto.'},favorites:{icon:'☆',title:'Favoritos',desc:'Guarda aquí herramientas, diseños o documentos a los que quieras acceder rápidamente.',action:'Aún no has agregado favoritos.'},templates:{icon:'▧',title:'Plantillas',desc:'Inicia tus diseños a partir de diagramas y procesos prediseñados.',action:'La biblioteca de plantillas se añadirá próximamente.'},import:{icon:'↥',title:'Importar',desc:'Trae archivos y diseños a tu espacio de trabajo.',action:'La importación de archivos se habilitará más adelante.'}};const d=pages[page]||pages.home;content.innerHTML=`<div class="ws-welcome"><div><h1>${d.title}</h1><p>${d.desc}</p></div><div class="ws-project-pill">Proyecto: <strong>${escapeHtml(activeProject?.name||'')}</strong></div></div><div class="ws-placeholder"><div class="ws-placeholder-icon">${d.icon}</div><h2>${d.title}</h2><p>${d.action}</p><button class="btn" style="margin-top:20px" onclick="workspacePage('home')">← Volver a Inicio</button></div>`}

async function deleteProject(id){if(!confirm('¿Eliminar este proyecto?'))return;if(guestMode){guestProjects=guestProjects.filter(p=>p.id!==id);renderProjects();return}try{const {error}=await supabaseClient.from('pfd_projects').delete().eq('id',id).eq('user_id',authUser.id);if(error)throw error;renderProjects();toast('Proyecto eliminado')}catch(err){console.error(err);toast('No se pudo eliminar el proyecto: '+(err.message||''))}}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
window.addEventListener('load',async()=>{applyTheme(localStorage.getItem('diagram_designer_theme_v1')||'light');supabaseClient=initSupabase();if(!supabaseClient){console.warn('Supabase no configurado. La interfaz de auth mostrará instrucciones.');return}try{const {data:{session}}=await supabaseClient.auth.getSession();authSession=session;authUser=session?.user||null;if(authUser)showDashboard();supabaseClient.auth.onAuthStateChange((_event,session)=>{authSession=session;authUser=session?.user||null;/* No navegar por eventos de refresco de sesión: conservar la pestaña y proyecto abiertos. */})}catch(e){console.error('Supabase session error',e)}});